#!/usr/bin/env node
/* Bundle the Studio document and store for the browser prototypes: design/shared/studio.js (generated, do not edit). */
import { buildSync } from "esbuild";
import { resolve, dirname } from "node:path";
const root = resolve(dirname(new URL(import.meta.url).pathname), "..");
buildSync({ entryPoints: [`${root}/src/studio/browser.ts`], bundle: true, format: "iife", platform: "browser", target: "es2020", minify: true, outfile: `${root}/design/shared/studio.js`, banner: { js: "/* Generated by scripts/build-studio-lib.mjs from src/studio. Do not edit. */" }, logLevel: "info" });
